def subtract(base, cuts):
    # 1. Normalize base and cuts: merge overlapping/adjacent intervals
    def merge_intervals(intervals):
        if not intervals:
            return []
        sorted_ints = sorted(intervals)
        merged = []
        curr_start, curr_end = sorted_ints[0]
        for next_start, next_end in sorted_ints[1:]:
            if next_start <= curr_end:
                curr_end = max(curr_end, next_end)
            else:
                merged.append((curr_start, curr_end))
                curr_start, curr_end = next_start, next_end
        merged.append((curr_start, curr_end))
        return merged

    # 2. Normalize cuts to a set of disjoint intervals
    normalized_cuts = merge_intervals(cuts)

    # 3. Subtract cuts from base
    # First, merge base to simplify the starting set
    normalized_base = merge_intervals(base)

    result = []
    for b_start, b_end in normalized_base:
        current_segments = [(b_start, b_end)]

        for c_start, c_end in normalized_cuts:
            next_segments = []
            for s_start, s_end in current_segments:
                # If no overlap
                if c_end <= s_start or c_start >= s_end:
                    next_segments.append((s_start, s_end))
                else:
                    # Left part
                    if s_start < c_start:
                        next_segments.append((s_start, c_start))
                    # Right part
                    if s_end > c_end:
                        next_segments.append((c_end, s_end))
            current_segments = next_segments

        result.extend(current_segments)

    # 4. Final pass to merge adjacent intervals in the result
    if not result:
        return []

    result.sort()
    final_result = []
    curr_start, curr_end = result[0]

    for i in range(1, len(result)):
        next_start, next_end = result[i]
        if next_start <= curr_end:
            curr_end = max(curr_end, next_end)
        else:
            final_result.append((curr_start, curr_end))
            curr_start, curr_end = next_start, next_end
    final_result.append((curr_start, curr_end))

    return final_result
