function debounce(fn, wait, options = {}) {
  let timeoutId = null;
  let lastResult;
  let lastArgs;
  let lastContext;
  let lastCallTime = 0;

  const leading = !!options.leading;
  const trailing = !!options.trailing !== false;

  function invoke() {
    const now = Date.now();
    const args = lastArgs;
    const context = lastContext;

    lastResult = fn.apply(context, args);

    lastArgs = null;
    lastContext = null;
    lastCallTime = now;

    return lastResult;
  }

  const debounced = function(...args) {
    const now = Date.now();
    lastArgs = args;
    lastContext = this;
    lastCallTime = now;

    const isInvokedNow = leading && !timeoutId;

    if (timeoutId) {
      clearTimeout(timeoutId);
    }

    timeoutId = setTimeout(() => {
      timeoutId = null;
      if (trailing && lastArgs !== null) {
        invoke();
      }
    }, wait);

    if (isInvokedNow) {
      return invoke();
    }
  };

  debounced.cancel = () => {
    if (timeoutId) {
      clearTimeout(timeoutId);
    }
    timeoutId = null;
    lastArgs = null;
    lastContext = null;
  };

  debounced.flush = () => {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
    if (lastArgs !== null) {
      return invoke();
    }
  };

  return debounced;
}

