function* zipLongest(fill, ...iterables) {
  if (iterables.length === 0) return;

  const iterators = iterables.map(iterable => {
    const it = iterable[Symbol.iterator] ? iterable[Symbol.iterator]() : null;
    return {
      iterator: it,
      done: false
    };
  });

  const activeCount = iterators.length;
  let currentActive = activeCount;

  while (currentActive > 0) {
    const row = [];
    for (let i = 0; i < iterators.length; i++) {
      const entry = iterators[i];
      if (entry.done) {
        row.push(fill);
      } else {
        try {
          const { value, done } = entry.iterator.next();
          if (done) {
            entry.done = true;
            currentActive--;
          } else {
            row.push(value);
          }
        } catch (e) {
          entry.done = true;
          currentActive--;
          row.push(fill);
        }
      }
    }
    yield row;
  }
}

module.exports = zipLongest;
