function createStore(reducer, initial) {
  let state = initial;
  let listeners = [];
  let isDispatching = false;

  const getState = () => state;

  const dispatch = (action) => {
    if (isDispatching) {
      throw new Error("Reducers, and for that the store, must be pure. You can't dispatch actions from inside reducers.");
    }

    isDispatching = true;
    try {
      const nextState = reducer(state, action);
      state = nextState;

      const snapshot = [...listeners];
      for (let i = 0; i < snapshot.length; i++) {
        listeners[i](state);
      }
    } finally {
      isDispatching = false;
    }
    return action;
  };

  const subscribe = (fn) => {
    listeners.push(fn);
    return () => {
      listeners = listeners.filter(l => l !== fn);
    };
  };

  return {
    getState,
    dispatch,
    subscribe
  };
}

module.exports = createStore;
