export type RouteParams = Record<string, string>;

export type RouteHandler<T extends RouteParams> = (params: T) => string;

export type RouteMap = Record<string, string>;

export function defineRoutes<T extends RouteMap>(routes: T): {
  [K in keyof T]: T[K] extends string ? RouteHandler<ExtractRouteParams<T[K]>> : never;
} {
  const result = {} as any;

  for (const [name, path] of Object.entries(routes)) {
    const paramNames: string[] = [];
    const segments = path.split("/");

    segments.forEach((segment) => {
      if (segment.startsWith(":") && segment.length > 1) {
        paramNames.push(segment.slice(1));
      }
    });

    result[name] = (params: any) => {
      let interpolated = path;
      paramNames.forEach((param) => {
        interpolated = interpolated.replace(`:${param}`, params[param]);
      });
      return interpolated;
    };
  }

  return result;
}

